('50000000-0000-0000-0000-000000000005', '30000000-0000-0000-0000-000000000001', 'ai', 'Thank you. I will create a service request for a technician to inspect the drum suspension damper.', 108, NOW() - INTERVAL '30 seconds'),
('50000000-0000-0000-0000-000000000006', '30000000-0000-0000-0000-000000000001', 'customer', 'Okay, will they be able to come tomorrow morning?', 128, NOW() - INTERVAL '10 seconds'),

