('50000000-0000-0000-0000-000000000007', '30000000-0000-0000-0000-000000000002', 'ai', 'Thank you for calling HomeCare support. How can I assist you today, Ms. Mehta?', 2, NOW() - INTERVAL '100 seconds'),
('50000000-0000-0000-0000-000000000008', '30000000-0000-0000-0000-000000000002', 'customer', 'Hello, my Daikin split AC in the master bedroom is not cooling. The fan is blowing air, but it is not cold at all.', 22, NOW() - INTERVAL '80 seconds'),
('50000000-0000-0000-0000-000000000009', '30000000-0000-0000-0000-000000000002', 'ai', 'Can you check if the outdoor unit is making a humming sound when you turn the temperature down to 18 degrees?', 45, NOW() - INTERVAL '57 seconds'),
('50000000-0000-0000-0000-000000000010', '30000000-0000-0000-0000-000000000002', 'customer', 'I just stepped out to the balcony. No, the outdoor fan is not spinning at all.', 74, NOW() - INTERVAL '28 seconds'),
('50000000-0000-0000-0000-000000000011', '30000000-0000-0000-0000-000000000002', 'ai', 'That indicates a capacitor or compressor trigger fault. Generating high-priority technician visit under your active warranty.', 95, NOW() - INTERVAL '7 seconds'),

