('50000000-0000-0000-0000-000000000012', '30000000-0000-0000-0000-000000000003', 'ai', 'Welcome to HomeCare VIP support. How may I assist you today, Ms. Kapoor?', 2, NOW() - INTERVAL '52 seconds'),
('50000000-0000-0000-0000-000000000013', '30000000-0000-0000-0000-000000000003', 'customer', 'Hi, my Voltas AC just beeped and the display is flashing E4.', 18, NOW() - INTERVAL '36 seconds'),
('50000000-0000-0000-0000-000000000014', '30000000-0000-0000-0000-000000000003', 'ai', 'Allow me a moment to check the error code reference for the Voltas Vectra Elite series.', 36, NOW() - INTERVAL '18 seconds'),

