('50000000-0000-0000-0000-000000000015', '30000000-0000-0000-0000-000000000007', 'ai', 'Welcome to HomeCare. How may I assist you today, Mr. Verma?', 2, NOW() - INTERVAL '59 minutes'),
('50000000-0000-0000-0000-000000000016', '30000000-0000-0000-0000-000000000007', 'customer', 'Hello, my Sony Bravia 55 inch TV has audio playing, but the screen is completely pitch black.', 25, NOW() - INTERVAL '58 minutes'),
('50000000-0000-0000-0000-000000000017', '30000000-0000-0000-0000-000000000007', 'ai', 'Let us perform a soft power reset. Could you unplug the main power cord from the wall socket for 60 seconds?', 52, NOW() - INTERVAL '57 minutes'),
('50000000-0000-0000-0000-000000000018', '30000000-0000-0000-0000-000000000007', 'customer', 'Alright, unplugged. Waiting... Okay, plugging it back in now.', 105, NOW() - INTERVAL '56 minutes'),
('50000000-0000-0000-0000-000000000019', '30000000-0000-0000-0000-000000000007', 'ai', 'Now press and hold the power button on the TV remote for 5 seconds until you see the Sony logo.', 125, NOW() - INTERVAL '55 minutes'),
('50000000-0000-0000-0000-000000000020', '30000000-0000-0000-0000-000000000007', 'customer', 'Oh excellent! The Sony logo just came up and the picture is back. Thank you!', 150, NOW() - INTERVAL '55 minutes')
