-- 9. KNOWLEDGE DOCUMENTS (15 standard diagnostic guides)
INSERT INTO public.knowledge_documents (
  id, title, category, appliance_type, description, content, source_url, status, last_updated_at, created_at
) VALUES
('80000000-0000-0000-0000-000000000001', 'AC — Cooling Troubleshooting Guide', 'Air Conditioner', 'air_conditioner', 'Step-by-step diagnostic workflow for split and inverter air conditioners blowing ambient air.', 'Diagnostic Steps:\n1. Mode & Temperature: Set to Cool mode at 18-20C.\n2. Outdoor Unit: Check if outdoor fan spins and compressor hums.\n3. Filter Check: Clean indoor nylon mesh filters.\n4. Coil Icing: Check for white frost on copper piping which indicates refrigerant leak.', NULL, 'Published', NOW() - INTERVAL '5 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000002', 'Washing Machine — Common Error Codes', 'Washing Machine', 'washing_machine', 'Mapping of digital error codes across Samsung, LG, and IFB washers.', 'Samsung:\n- 4C/4E: Water supply error. Check inlet tap & mesh.\n- 5C/5E: Drain failure. Clean bottom filter.\n- Ub/UE: Unbalanced spin load.\nLG:\n- OE: Drain timeout.\n- IE: Water inlet failure.\n- CL: Child lock active (Hold Rinse+Spin 3 sec).', NULL, 'Published', NOW() - INTERVAL '8 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000003', 'Washing Machine — Excessive Vibration Troubleshooting', 'Washing Machine', 'washing_machine', 'Guidelines for identifying drum damper failure and transit shipping bolt presence.', 'Symptom Analysis:\n1. Check if 4 rear transit shipping bolts were unscrewed during installation.\n2. Confirm all 4 feet are firmly leveled.\n3. Worn suspension dampers cause rhythmic thumping on spin cycle.', NULL, 'Published', NOW() - INTERVAL '2 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000004', 'Refrigerator — Not Cooling Diagnostic Protocol', 'Refrigerator', 'refrigerator', 'Diagnostic procedures for double door and frost-free refrigerators.', 'Root Causes:\n- Freezer cold but fridge warm: Evaporator air return duct frozen, circulation fan jammed, or air damper baffle broken.\n- Both warm: Compressor starter relay or inverter board malfunction.', NULL, 'Published', NOW() - INTERVAL '10 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000005', 'Refrigerator — Ice Formation & Frosting Guide', 'Refrigerator', 'refrigerator', 'Resolving excessive frost accumulation in frost-free systems.', 'Components in Defrost Loop:\n1. Defrost heater element.\n2. Bi-metal thermostat sensor.\n3. Thermal fuse.\n4. Main control board defrost timer interval.', NULL, 'Published', NOW() - INTERVAL '12 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000006', 'Water Purifier — Filter Replacement & Service Intervals', 'Water Purifier', 'water_purifier', 'Preventative maintenance schedule for Sediment, Carbon, and RO filters.', 'Replacement Timeline:\n- Pre-filter: 3 to 4 months.\n- Sediment & Pre-carbon: 12 months.\n- RO Membrane: 24 to 36 months.\n- UV Lamp: Replace when UV fail alarm (2 beeps) activates.', NULL, 'Published', NOW() - INTERVAL '6 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000007', 'TV — No Display Troubleshooting Protocol', 'Television', 'television', 'Diagnosing black screen with sound and HDMI signal freezes.', 'Diagnostic Steps:\n1. Flashlight test: Shine light against panel at 45 degrees. If faint video is visible, backlight array or LED driver has failed.\n2. Soft power reset: Disconnect power cord for 60 seconds.', NULL, 'Published', NOW() - INTERVAL '9 days', NOW() - INTERVAL '30 days'),
('80000000-0000-0000-0000-000000000008', 'Warranty Policy & Coverage Guidelines', 'Warranty', NULL, 'Standard manufacturer warranty limits, component terms, and out-of-warranty fees.', 'Coverage Framework:\n- Comprehensive Machine: 1 Year.\n- Inverter Compressors: 10 Years.\n- Washing Machine Inverter Motors: 10 Years.\n- TV Panels: 1 to 2 Years depending on model.', NULL, 'Published', NOW() - INTERVAL '19 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000009', 'Installation Guidelines — Air Conditioners', 'Installation', 'air_conditioner', 'SOPs for copper piping, vacuuming, and dedicated 16A MCB breakers.', 'Standards:\n1. Minimum 3.0 meters copper tubing.\n2. Vacuuming down to 500 microns for 15 minutes before gas release.\n3. Dedicated 16A C-curve MCB breaker.', NULL, 'Published', NOW() - INTERVAL '15 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000010', 'Washing Machine — Installation & Transit Bolt Protocol', 'Installation', 'washing_machine', 'Protocol for shipping bolt extraction and drain hose loop elevation.', 'Key Standards:\n1. Unscrew all 4 rear shipping bolts before running wash cycle.\n2. In front loaders, ensure drain hose loops up to 60cm height before waste trap.', NULL, 'Published', NOW() - INTERVAL '16 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000011', 'Water Purifier — High TDS Input Troubleshooting', 'Troubleshooting', 'water_purifier', 'Managing borewell input water with TDS exceeding 1500 ppm.', 'Guidelines:\n- Municipal Supply (TDS < 300 ppm): Tune mineral controller to 80-120 ppm.\n- Borewell Supply (> 1500 ppm): High recovery membrane with anti-scalant cartridge.', NULL, 'Published', NOW() - INTERVAL '11 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000012', 'AC — Strange Odors & Chemical Smells Diagnosis', 'Air Conditioner', 'air_conditioner', 'Identifying mold mildew, burning plastic, or vinegar odors.', 'Odor Guide:\n- Sour / Musty: Mold on wet evaporator coil. Foam wash required.\n- Burning Plastic: Electrical terminal or fan motor overheat. Cut power immediately.', NULL, 'Published', NOW() - INTERVAL '7 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000013', 'Television — Smart TV Wi-Fi Connection Recovery', 'Television', 'television', 'Resolving DNS issues and dual-band 2.4/5GHz connection drops.', 'Steps:\n1. Time sync: Toggle network-provided NTP time.\n2. Manual DNS: Set primary to 8.8.8.8.\n3. Split 2.4GHz and 5GHz SSIDs on home router.', NULL, 'Published', NOW() - INTERVAL '13 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000014', 'Refrigerator — Strange Noises & Acoustic Guide', 'Refrigerator', 'refrigerator', 'Normal bubbling vs abnormal clicking and fan screeching.', 'Sounds:\n- Gurgling: Normal liquid refrigerant flow.\n- Loud Clicking with No Cooling: PTC starter relay overload tripping.\n- High-pitched Screech: Evaporator fan blade touching frost.', NULL, 'Published', NOW() - INTERVAL '18 days', NOW() - INTERVAL '40 days'),
('80000000-0000-0000-0000-000000000015', 'Customer Escalation & Safety Advisory Guidelines', 'Troubleshooting', NULL, 'Mandatory AI agent escalation protocol for fire, water leakage, or high frustration.', 'Critical Triggers:\n1. Smoke or electrical fire risk.\n2. Flooding or water damage hazard.\n3. Repeat failure within 14 days.\n4. Frustration score high.', NULL, 'Published', NOW() - INTERVAL '4 days', NOW() - INTERVAL '40 days')
